# WAR ARENA - Security + Observability + CI - Installer
# Adds: rate limiter, CORS, security headers, structured logger, CI pipeline.
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-security.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - Security + CI installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/api/security.ts" ""
Write-B64 "src/api/httpServer.ts" ""
Write-B64 "src/deploy/server.ts" ""
Write-B64 "src/deploy/env.ts" ""
Write-B64 "tests/unit/security.test.ts" ""
Write-B64 ".github/workflows/ci.yml" ""
Write-B64 ".env.example" ""

Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
Write-Host ""; Write-Host "Security + CI installed. Expected: 974 passed + 1 skipped." -ForegroundColor Green
